import { Component, OnInit } from '@angular/core';
import { FormArray, FormBuilder, FormGroup } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';

@Component({
  selector: 'app-land-details',
  templateUrl: './land-details.page.html',
  styleUrls: ['./land-details.page.scss'],
})
export class LandDetailsPage implements OnInit {

  owner = [
    {label: "Leased",value: 1 },
    {label: "Rented",value: 2 },
    {label: "Owned",value: 3 },
 ]
  routeData: any;
  status: any;
  uidse: any;
  form: FormGroup = new FormGroup({});
  landDetails: FormArray;
  activeData: boolean;
  onRented: boolean;
  
  constructor(private route: ActivatedRoute, 
     private formBuilder: FormBuilder,
    private router: Router) { }

  ngOnInit() {
    this.form = this.formBuilder.group({
     landDetails: this.formBuilder.array([this.landDataDetails()]),
    })
     }
 
  ionViewDidEnter() {
    this.routeData = this.route.snapshot;
    this.status = this.routeData.queryParams.status;
    this.uidse = this.routeData.queryParams.uidse;
  }

  onOfChange(event,id,i){
    console.log(event,id,i)
    if(id == 2){
      this.activeData = false
      this.form.controls['landDetails']['controls'][i].controls['resp5'].setValue(false);
      this.form.controls['landDetails']['controls'][i].controls['resp5'].updateValueAndValidity();
    }
    if(id == 1 ){
      this.activeData = true
      this.form.controls['landDetails']['controls'][i].controls['resp5'].setValue(true);
      this.form.controls['landDetails']['controls'][i].controls['resp5'].updateValueAndValidity();
    }
  }

  onOfdataChange(data){
    console.log(data)
  if(data == 2) {
    this.onRented = true
  } else {
    this.onRented = false
  }
  }

  landDataDetails()
  {
    return this.formBuilder.group({
      resp1: [""],
      resp2: [""],
      resp3: [""],
      resp4: [""],
      resp5: [false]
    })  
  }
  
  landArray() {
    return (this.form.controls.landDetails as FormArray).controls;
  }

  addlandData() {
    this.landDetails = this.form.controls.landDetails as FormArray;
    this.landDetails.push(this.landDataDetails());
    console.log(this.landDetails,"data")
  }
  
  onSave()
  {
    this.router.navigate(['/tabs/regulator-section'], {
      queryParams: { status: 4, "uidse": this.uidse }, skipLocationChange: false
    });
  
  }
   goToBack()
  {
    this.router.navigate(['/tabs/regulator-section']);
  }

}
